import SwiftUI
import UIKit

enum AppVisualAssets {
    private static let autoFeedBase64 = ""
    private static let multiSpaceSyncBase64 = ""
    private static let smartPostBase64 = ""
    private static let appLogoBase64 = ""

    static let autoFeedImage: UIImage? = {
        guard let data = Data(base64Encoded: autoFeedBase64) else { return nil }
        return UIImage(data: data)
    }()

    static let multiSpaceSyncImage: UIImage? = {
        guard let data = Data(base64Encoded: multiSpaceSyncBase64) else { return nil }
        return UIImage(data: data)
    }()

    static let smartPostImage: UIImage? = {
        guard let data = Data(base64Encoded: smartPostBase64) else { return nil }
        return UIImage(data: data)
    }()

    static let appLogoImage: UIImage? = {
        guard let data = Data(base64Encoded: appLogoBase64) else { return nil }
        return UIImage(data: data)
    }()
}
